// =============================================================================
// File           : Entity.cs
// Layer          : Domain / Common
// Purpose        : Base class of every entity: identity (Id) and creation time (CreatedAt).
// Logic          : Ids are time-ordered GUIDs (v7) generated by the entity itself, so no database round-trip
//                  is needed to know an entity's identity. Guard helpers keep factory methods short.
// Implementation : Setters are private so state only changes through behaviour methods. The protected
//                  parameterless constructor exists solely for EF Core materialisation.
// =============================================================================
using CardioSense.Domain.Exceptions;

namespace CardioSense.Domain.Common;

/// <summary>Base type for all domain entities.</summary>
public abstract class Entity
{
    /// <summary>Used by EF Core when loading an entity from the database.</summary>
    protected Entity()
    {
    }

    /// <summary>Creates a new entity with a fresh Id and the given creation time.</summary>
    protected Entity(DateTimeOffset createdAt)
    {
        Id = Guid.CreateVersion7();
        CreatedAt = createdAt;
    }

    /// <summary>Unique identifier of the entity.</summary>
    public Guid Id { get; private set; }

    /// <summary>When the entity was created (UTC offset preserved).</summary>
    public DateTimeOffset CreatedAt { get; private set; }

    /// <summary>Guard: the id must not be empty.</summary>
    protected static Guid RequireId(Guid value, string name) =>
        value == Guid.Empty ? throw new DomainException($"{name} must not be empty.") : value;

    /// <summary>Guard: required text must be present; returns it trimmed and within the length limit.</summary>
    protected static string RequireText(string? value, string name, int maxLength)
    {
        var trimmed = value?.Trim();
        if (string.IsNullOrEmpty(trimmed))
        {
            throw new DomainException($"{name} is required.");
        }

        return trimmed.Length <= maxLength
            ? trimmed
            : throw new DomainException($"{name} must not exceed {maxLength} characters.");
    }

    /// <summary>Guard: optional text; blank becomes null, otherwise trimmed and length-checked.</summary>
    protected static string? RequireOptionalText(string? value, string name, int maxLength) =>
        string.IsNullOrWhiteSpace(value) ? null : RequireText(value, name, maxLength);

    /// <summary>Guard: the number must lie inside the inclusive range.</summary>
    protected static int RequireRange(int value, int min, int max, string name) =>
        value >= min && value <= max
            ? value
            : throw new DomainException($"{name} must be between {min} and {max}.");
}
